/**
 * Seed the default spending hierarchy (Importance areas + Groupings, and map
 * the default categories into them) for a family. Idempotent server-side —
 * safe to call whenever a family has no hierarchy yet. Mirrors the
 * lazy-initialization pattern used for default categories.
 */
async createDefaultHierarchy(familyId: string): Promise<void> {
	if (!familyId) {
		throw new Error('Family ID is required');
	}

	const { error } = await this.supabase.rpc('create_default_hierarchy', {
		p_family_id: familyId
	});

	if (error) {
		throw new Error(error.message);
	}
}

/**
 * Assign a Category to a Grouping (or clear it back to Uncategorized).
 *
 * The spending-hierarchy editor's core mutation: a category with no
 * `group_id` falls into the report's Uncategorized bucket, so this is how a
 * custom or renamed category gets pulled into a real Grouping without SQL.
 * Pass `null` to unassign.
 */

