/**
 * Seed the "Sample Family (DEMO)" into the REMOTE project for documentation
 * screenshots/videos and manual testing. See docs/demo-seed.md.
 *
 * Auto-cleans any prior demo artifacts first, then rebuilds from scratch, so
 * every run yields the same known-good state. Requires the service-role key.
 *
 *   op run --env-file=.env -- npm run seed:demo
 */
import { randomInt } from 'node:crypto';
import type { SupabaseClient } from '@supabase/supabase-js';
import {
	FAMILY_NAME,
	MEMBER_EMAIL,
	OWNER_EMAIL,
	createAdminClient,
	readConfig,
	targetHost,
	teardownDemo
} from './common.ts';
import { generateDemoData } from './data.ts';

/** Password satisfying the app policy: 16+ chars, one each of upper/lower/digit/special. */
function generatePassword(): string {
	const upper = 'ABCDEFGHJKLMNPQRSTUVWXYZ';
	const lower = 'abcdefghijkmnpqrstuvwxyz';
	const digit = '23456789';
	const special = '!@#$%^&*-_';
	const pool = upper + lower + digit + special;
	const chars = Array.from({ length: 20 }, () => pool[randomInt(pool.length)]);
	// Guarantee one of each class.
	chars[0] = upper[randomInt(upper.length)];
	chars[1] = lower[randomInt(lower.length)];
	chars[2] = digit[randomInt(digit.length)];
	chars[3] = special[randomInt(special.length)];
	return chars.join('');
}

async function createUser(admin: SupabaseClient, email: string, password: string): Promise<string> {
	const { data, error } = await admin.auth.admin.createUser({
		email,
		password,
		email_confirm: true
	});
	if (error || !data.user) throw new Error(`createUser(${email}) failed: ${error?.message}`);
	return data.user.id;
}

/** Insert in chunks to stay well under any payload limit. */
async function insertAll(
	admin: SupabaseClient,
	table: string,
	rows: Record<string, unknown>[],
	chunkSize = 500
): Promise<void> {
	for (let i = 0; i < rows.length; i += chunkSize) {
		const chunk = rows.slice(i, i + chunkSize);
		const { error } = await admin.from(table).insert(chunk);
		if (error) throw new Error(`insert into ${table} failed: ${error.message}`);
	}
}

async function main(): Promise<void> {
	const config = readConfig();
	const admin = createAdminClient(config);
	console.log(`\nDemo seed → target: ${targetHost(config.url)}\n`);

	console.log('Cleaning any existing demo data…');
	const cleaned = await teardownDemo(admin);
	console.log(`  removed ${cleaned.usersDeleted} user(s), ${cleaned.familiesDeleted} family(ies)`);

	// --- Auth users -----------------------------------------------------------
	const password = generatePassword();
	console.log('Creating demo users…');
	const ownerId = await createUser(admin, OWNER_EMAIL, password);
	const memberId = await createUser(admin, MEMBER_EMAIL, password);

	// --- Family + members -----------------------------------------------------
	console.log('Creating family + members…');
	const { data: family, error: famErr } = await admin
		.from('families')
		.insert({ name: FAMILY_NAME, created_by: ownerId })
		.select('id')
		.single();
	if (famErr || !family) throw new Error(`create family failed: ${famErr?.message}`);
	const familyId = family.id as string;

	const { error: memErr } = await admin.from('family_members').insert([
		{ family_id: familyId, user_id: ownerId, status: 'active', role: 'owner', is_default: true },
		{ family_id: familyId, user_id: memberId, status: 'active', role: 'member', is_default: true }
	]);
	if (memErr) throw new Error(`create family_members failed: ${memErr.message}`);

	// --- Categories + spending hierarchy (reuse the app's own RPCs) -----------
	console.log('Seeding default categories + spending hierarchy…');
	const { error: catErr } = await admin.rpc('create_default_categories', { p_family_id: familyId });
	if (catErr) throw new Error(`create_default_categories failed: ${catErr.message}`);
	const { error: hierErr } = await admin.rpc('create_default_hierarchy', { p_family_id: familyId });
	if (hierErr) throw new Error(`create_default_hierarchy failed: ${hierErr.message}`);

	const { data: categories, error: catFetchErr } = await admin
		.from('categories')
		.select('id, name')
		.eq('family_id', familyId);
	if (catFetchErr || !categories)
		throw new Error(`fetch categories failed: ${catFetchErr?.message}`);
	const categoryIdByName = new Map<string, string>(
		categories.map((c) => [String(c.name).toLowerCase(), c.id as string])
	);

	// --- Generate + insert the dataset ---------------------------------------
	console.log('Generating receipts + transactions…');
	const data = generateDemoData({ familyId, ownerId, memberId, categoryIdByName });

	await insertAll(admin, 'transactions', data.transactions);
	await insertAll(admin, 'receipts', data.receipts);
	await insertAll(admin, 'expense_categories', data.expenseCategories);

	// --- Report ---------------------------------------------------------------
	const matched = data.receipts.filter((r) => r.matched_transaction_id).length;
	console.log('\n✓ Demo data seeded.');
	console.log(`  Family:        ${FAMILY_NAME} (${familyId})`);
	console.log(`  Categories:    ${categories.length}`);
	console.log(`  Receipts:      ${data.receipts.length} (${matched} matched to a transaction)`);
	console.log(`  Transactions:  ${data.transactions.length}`);
	console.log(`  Categorized:   ${data.expenseCategories.length}`);
	console.log('\n  Log in at http://localhost:5173/login  (run: npm run dev)');
	console.log('  ┌──────────────────────────────────────────────────────────');
	console.log(`  │ Owner:    ${OWNER_EMAIL}`);
	console.log(`  │ Member:   ${MEMBER_EMAIL}`);
	console.log(`  │ Password: ${password}`);
	console.log('  └──────────────────────────────────────────────────────────');
	console.log('\n  Tear down with: npm run seed:demo:teardown\n');
}

main().catch((err) => {
	console.error(`\n✗ Demo seed failed: ${err instanceof Error ? err.message : err}\n`);
	process.exit(1);
});

